package com.example.sgva.usecases

import com.example.sgva.domain.DatosInsuficientesException
import com.example.sgva.domain.IndicadorCalidad
import com.example.sgva.domain.ReporteEjecutivo

/**
 * Consolida el reporte ejecutivo (Fase 4 del anteproyecto — integración de
 * reportes): agrupa los indicadores de calidad de los Módulos 1 y 2 con las
 * respuestas de encuesta de percepción del Módulo 3 ya registradas. Por
 * composición sobre los casos de uso de cálculo ya existentes (mismo patrón
 * que [GenerarMatrizRadarUseCase]); no accede al repositorio directamente.
 *
 * La exportación a un formato físico concreto (PDF) es responsabilidad
 * exclusiva de la infraestructura (`GeneradorReportePdf`); este caso de uso
 * solo produce el [ReporteEjecutivo], un objeto de dominio puro.
 */
class GenerarReporteEjecutivoUseCase(
    private val calcularEvolucionMatricula: CalcularEvolucionMatriculaUseCase,
    private val calcularTasaDesercion: CalcularTasaDesercionUseCase,
    private val consolidarSaberPro: ConsolidarPuntajesSaberProUseCase,
    private val calcularDistribucionFormacion: CalcularDistribucionFormacionUseCase,
    private val calcularCapacidadInstalada: CalcularCapacidadInstaladaUseCase,
    private val consultarRespuestasEncuesta: ConsultarRespuestasEncuestaUseCase,
) {

    /**
     * @param cohorte cohorte para la tasa de deserción; a diferencia de los
     *   demás indicadores, esa cohorte es obligatoria en su caso de uso
     *   (`DESIGN_SGVA.md` §2) y no tiene un valor por defecto razonable para
     *   un reporte sin cohorte específica — se incluye solo cuando se indica.
     */
    fun ejecutar(periodo: String? = null, facultad: String? = null, cohorte: String? = null): ReporteEjecutivo {
        val indicadores = mutableListOf<IndicadorCalidad>()
        indicadores += calcularEvolucionMatricula.ejecutar(facultad)
        indicadores += sinDatosInsuficientes { consolidarSaberPro.ejecutar(facultad) }
        indicadores += sinDatosInsuficientes { calcularDistribucionFormacion.ejecutar(periodo, facultad) }
        indicadores += sinDatosInsuficientes { listOf(calcularCapacidadInstalada.ejecutar(periodo, facultad)) }

        cohorte?.trim()?.takeIf { it.isNotEmpty() }?.let { cohorteIndicada ->
            indicadores += sinDatosInsuficientes { listOf(calcularTasaDesercion.ejecutar(cohorteIndicada, facultad)) }
        }

        return ReporteEjecutivo(
            indicadores = indicadores.toList(),
            respuestasEncuesta = consultarRespuestasEncuesta.listarTodas(),
        )
    }

    /**
     * Un reporte ejecutivo agrega lo que hay disponible: si una sección no
     * tiene datos suficientes para calcularse (ej. sin puntajes Saber Pro
     * aún), se omite en vez de impedir la generación del resto del reporte.
     */
    private fun sinDatosInsuficientes(calculo: () -> List<IndicadorCalidad>): List<IndicadorCalidad> =
        try {
            calculo()
        } catch (sinDatos: DatosInsuficientesException) {
            emptyList()
        }
}

package com.example.sgva.usecases

import com.example.sgva.domain.AcademicDataRepository
import com.example.sgva.domain.Caracteristica
import com.example.sgva.domain.ConfiguracionPonderaciones
import com.example.sgva.domain.ResultadoAutoevaluacion

/**
 * Módulo 4 — resultado de autoevaluación del programa (`DESIGN_SGVA.md` §0.1
 * "Reglas de cálculo del resultado de autoevaluación" y §2).
 *
 * Calcula, para un [programa] y un [periodo], el promedio por característica,
 * por factor y global del modelo institucional de 12 factores y 48
 * características, a partir de los `ResultadoEncuestaPregunta` y
 * `EvaluacionDocumental` ya registrados. El universo de factores y
 * características, y todos los pesos usados en la mezcla, provienen
 * exclusivamente de [configuracion]: este caso de uso no hardcodea ningún
 * peso ni ningún identificador de factor o característica.
 *
 * Aplica exactamente las reglas de `DESIGN_SGVA.md` §0.1, sin criterios
 * adicionales no documentados.
 */
class CalcularResultadoAutoevaluacionUseCase(
    private val repositorio: AcademicDataRepository,
    private val configuracion: ConfiguracionPonderaciones,
) {

    fun ejecutar(programa: String, periodo: String): ResultadoAutoevaluacion {
        val promediosEncuestaPorCaracteristica = repositorio.listarResultadosEncuestaPregunta()
            .filter { it.programa == programa && it.periodo == periodo }
            .groupBy { it.caracteristica }
            .mapValues { (_, resultados) -> promedioDeEncuesta(resultados.mapNotNull { it.promedio }) }

        val documentalPorCaracteristica = repositorio.listarEvaluacionesDocumentales()
            .filter { it.programa == programa && it.periodo == periodo }
            .associateBy { it.caracteristica }

        val promediosPorCaracteristica = configuracion.caracteristicas.associate { caracteristica ->
            caracteristica.id to promedioDeCaracteristica(
                resultadoEncuesta = promediosEncuestaPorCaracteristica[caracteristica.id],
                documental = documentalPorCaracteristica[caracteristica.id]?.calificacion,
            )
        }

        val promediosPorFactor = configuracion.pesosFactores.keys.associateWith { factor ->
            promedioPonderadoReponderado(
                caracteristicasDelFactor(factor).mapNotNull { caracteristica ->
                    promediosPorCaracteristica[caracteristica.id]?.let { it to caracteristica.ponderacion }
                },
            )
        }

        val promedioGlobal = promedioPonderadoReponderado(
            configuracion.pesosFactores.mapNotNull { (factor, peso) ->
                promediosPorFactor[factor]?.let { it to peso }
            },
        )

        return ResultadoAutoevaluacion(
            programa = programa,
            periodo = periodo,
            promediosPorCaracteristica = promediosPorCaracteristica,
            promediosPorFactor = promediosPorFactor,
            promedioGlobal = promedioGlobal,
        )
    }

    private fun caracteristicasDelFactor(factor: String): List<Caracteristica> =
        configuracion.caracteristicas.filter { it.factor == factor }

    /**
     * Regla 1 de §0.1: promedio de los promedios de las preguntas con valor
     * de la característica, o ausente si ninguna pregunta tiene valor.
     */
    private fun promedioDeEncuesta(promedios: List<Double>): Double? =
        if (promedios.isEmpty()) null else promedios.average()

    /**
     * Regla 2 de §0.1: mezcla documental/encuesta de una característica, el
     * valor documental completo si la encuesta está ausente, o ausente si no
     * hay evaluación documental.
     */
    private fun promedioDeCaracteristica(resultadoEncuesta: Double?, documental: Double?): Double? = when {
        documental == null -> null
        resultadoEncuesta == null -> documental
        else -> documental * configuracion.pesoDocumental + resultadoEncuesta * configuracion.pesoEncuestas
    }

    /**
     * Reglas 3 y 4 de §0.1: promedio ponderado de los valores presentes,
     * reponderando sus pesos de configuración entre sí. Ausente si no hay
     * ningún valor presente, o si los pesos de los valores presentes suman
     * cero (no hay ninguna base de reponderación válida).
     */
    private fun promedioPonderadoReponderado(valoresConPeso: List<Pair<Double, Double>>): Double? {
        if (valoresConPeso.isEmpty()) return null
        val sumaPesos = valoresConPeso.sumOf { it.second }
        if (sumaPesos == 0.0) return null
        return valoresConPeso.sumOf { (valor, peso) -> valor * peso } / sumaPesos
    }
}

package com.example.sgva.infrastructure.reporting

import com.example.sgva.domain.ReporteEjecutivo
import org.apache.pdfbox.pdmodel.PDDocument
import org.apache.pdfbox.pdmodel.PDPage
import org.apache.pdfbox.pdmodel.PDPageContentStream
import org.apache.pdfbox.pdmodel.common.PDRectangle
import org.apache.pdfbox.pdmodel.font.PDFont
import org.apache.pdfbox.pdmodel.font.PDType1Font
import org.apache.pdfbox.pdmodel.font.Standard14Fonts
import org.springframework.stereotype.Component
import java.io.ByteArrayOutputStream
import java.time.LocalDateTime
import java.time.format.DateTimeFormatter

/**
 * Genera el PDF físico de un [ReporteEjecutivo] (Fase 4 del anteproyecto —
 * integración de reportes, `DESIGN_SGVA.md` §4). Única clase del proyecto que
 * depende de la librería de generación de documentos (Apache PDFBox); el
 * dominio y los casos de uso no la conocen ni dependen de ella.
 */
@Component
class GeneradorReportePdf {

    fun generar(reporte: ReporteEjecutivo): ByteArray {
        PDDocument().use { documento ->
            val lienzo = LienzoReporte(documento)

            lienzo.titulo("Reporte Ejecutivo SGVA")
            lienzo.subtitulo("Generado el " + FORMATO_FECHA.format(LocalDateTime.now()))

            lienzo.seccion("Indicadores de Calidad")
            if (reporte.indicadores.isEmpty()) {
                lienzo.linea("No hay indicadores disponibles.")
            } else {
                lienzo.tabla(
                    encabezados = listOf("Nombre", "Valor", "Periodo", "Facultad"),
                    anchos = listOf(220f, 70f, 90f, 120f),
                    filas = reporte.indicadores.map {
                        listOf(it.nombre, "%.2f".format(it.valor), it.periodo, it.facultad)
                    },
                )
            }

            lienzo.seccion("Respuestas de Encuesta")
            if (reporte.respuestasEncuesta.isEmpty()) {
                lienzo.linea("No hay respuestas de encuesta registradas.")
            } else {
                lienzo.tabla(
                    encabezados = listOf("Id", "Estamento", "Factor", "Calificación", "Periodo"),
                    anchos = listOf(80f, 90f, 180f, 80f, 70f),
                    filas = reporte.respuestasEncuesta.map {
                        listOf(it.id, it.estamento.name, it.factor, it.calificacion.toString(), it.periodo)
                    },
                )
            }

            lienzo.cerrar()

            return ByteArrayOutputStream().use { salida ->
                documento.save(salida)
                salida.toByteArray()
            }
        }
    }

    companion object {
        private val FORMATO_FECHA = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")
    }
}

/**
 * Maneja el posicionamiento vertical y la paginación automática del PDF:
 * abre una página nueva cuando el contenido no cabe en la actual. Cada
 * fragmento de texto se dibuja en su propio bloque `beginText`/`endText` con
 * coordenadas absolutas, evitando la aritmética de desplazamientos relativos
 * de PDFBox.
 */
private class LienzoReporte(private val documento: PDDocument) {

    private val fuenteTitulo = PDType1Font(Standard14Fonts.FontName.HELVETICA_BOLD)
    private val fuenteSeccion = PDType1Font(Standard14Fonts.FontName.HELVETICA_BOLD)
    private val fuenteTexto = PDType1Font(Standard14Fonts.FontName.HELVETICA)

    private val margenIzquierdo = 50f
    private val margenSuperior = 50f
    private val margenInferior = 50f
    private val altoLinea = 16f

    private var contenido: PDPageContentStream = abrirPagina()
    private var y: Float = alturaUtilInicial()

    fun titulo(texto: String) {
        dibujar(texto, margenIzquierdo, y, fuenteTitulo, 18f)
        y -= 26f
    }

    fun subtitulo(texto: String) {
        dibujar(texto, margenIzquierdo, y, fuenteTexto, 10f)
        y -= 24f
    }

    fun seccion(texto: String) {
        asegurarEspacio(altoLinea * 2)
        dibujar(texto, margenIzquierdo, y, fuenteSeccion, 13f)
        y -= altoLinea
    }

    fun linea(texto: String) {
        asegurarEspacio(altoLinea)
        dibujar(texto, margenIzquierdo, y, fuenteTexto, 10f)
        y -= altoLinea
    }

    fun tabla(encabezados: List<String>, anchos: List<Float>, filas: List<List<String>>) {
        asegurarEspacio(altoLinea)
        filaTabla(encabezados, anchos, fuenteSeccion)
        val yLineaSeparadora = y + 4f
        contenido.moveTo(margenIzquierdo, yLineaSeparadora)
        contenido.lineTo(margenIzquierdo + anchos.sum(), yLineaSeparadora)
        contenido.stroke()
        y -= altoLinea

        for (fila in filas) {
            asegurarEspacio(altoLinea)
            filaTabla(fila, anchos, fuenteTexto)
            y -= altoLinea
        }
        y -= altoLinea / 2
    }

    fun cerrar() {
        contenido.close()
    }

    private fun filaTabla(valores: List<String>, anchos: List<Float>, fuente: PDFont) {
        var x = margenIzquierdo
        for ((valor, ancho) in valores.zip(anchos)) {
            dibujar(ajustarAncho(valor, fuente, 9f, ancho), x, y, fuente, 9f)
            x += ancho
        }
    }

    private fun dibujar(texto: String, x: Float, y: Float, fuente: PDFont, tamano: Float) {
        contenido.beginText()
        contenido.setFont(fuente, tamano)
        contenido.newLineAtOffset(x, y)
        contenido.showText(texto)
        contenido.endText()
    }

    private fun ajustarAncho(texto: String, fuente: PDFont, tamano: Float, anchoMaximo: Float): String {
        if (anchoTexto(texto, fuente, tamano) <= anchoMaximo) return texto
        var recorte = texto
        while (recorte.isNotEmpty() && anchoTexto("$recorte...", fuente, tamano) > anchoMaximo) {
            recorte = recorte.dropLast(1)
        }
        return if (recorte.isEmpty()) texto else "$recorte..."
    }

    private fun anchoTexto(texto: String, fuente: PDFont, tamano: Float): Float =
        fuente.getStringWidth(texto) / 1000f * tamano

    private fun asegurarEspacio(alturaNecesaria: Float) {
        if (y - alturaNecesaria < margenInferior) {
            contenido.close()
            contenido = abrirPagina()
            y = alturaUtilInicial()
        }
    }

    private fun abrirPagina(): PDPageContentStream {
        val pagina = PDPage(PDRectangle.LETTER)
        documento.addPage(pagina)
        return PDPageContentStream(documento, pagina)
    }

    private fun alturaUtilInicial(): Float = PDRectangle.LETTER.height - margenSuperior
}

package com.example.sgva.infrastructure.web

import com.example.sgva.infrastructure.reporting.GeneradorReportePdf
import com.example.sgva.usecases.GenerarReporteEjecutivoUseCase
import org.springframework.http.ContentDisposition
import org.springframework.http.HttpHeaders
import org.springframework.http.MediaType
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.RestController

/**
 * Adaptador de entrada REST (Primary Adapter) de los reportes ejecutivos
 * (Fase 4 del anteproyecto — integración de reportes, `DESIGN_SGVA.md` §4).
 * Delega la consolidación de datos en [GenerarReporteEjecutivoUseCase] y la
 * generación física del PDF en [GeneradorReportePdf]; no reimplementa
 * lógica de negocio ni de renderizado.
 */
@RestController
@RequestMapping("/api/reportes")
class ReporteController(
    private val generarReporteEjecutivo: GenerarReporteEjecutivoUseCase,
    private val generadorReportePdf: GeneradorReportePdf,
) {

    @GetMapping("/ejecutivo", produces = [MediaType.APPLICATION_PDF_VALUE])
    fun obtenerReporteEjecutivo(
        @RequestParam periodo: String?,
        @RequestParam facultad: String?,
        @RequestParam cohorte: String?,
    ): ResponseEntity<ByteArray> {
        val reporte = generarReporteEjecutivo.ejecutar(periodo, facultad, cohorte)
        val pdf = generadorReportePdf.generar(reporte)

        val nombreArchivo = periodo?.trim()?.takeIf { it.isNotEmpty() }
            ?.let { "reporte-ejecutivo-$it.pdf" }
            ?: "reporte-ejecutivo.pdf"

        return ResponseEntity.ok()
            .contentType(MediaType.APPLICATION_PDF)
            .header(
                HttpHeaders.CONTENT_DISPOSITION,
                ContentDisposition.attachment().filename(nombreArchivo).build().toString(),
            )
            .body(pdf)
    }
}

package com.example.sgva.application

import com.example.sgva.domain.Caracteristica
import com.example.sgva.domain.ConfiguracionPonderaciones
import com.example.sgva.domain.EvaluacionDocumental
import com.example.sgva.domain.ResultadoEncuestaPregunta
import com.example.sgva.domain.TipoEstamento
import com.example.sgva.usecases.CalcularResultadoAutoevaluacionUseCase
import org.junit.jupiter.api.Test
import kotlin.test.assertEquals
import kotlin.test.assertNull

/**
 * Verifica `CalcularResultadoAutoevaluacionUseCase` contra las reglas de
 * cálculo de `DESIGN_SGVA.md` §0.1, con un catálogo sintético de dos factores
 * (F1 con C1/C2, F2 con C3/C4) y una mezcla encuestas/documental de 40 %/60 %.
 * Los pesos no corresponden al modelo 2025 real: son datos de prueba para
 * aislar cada regla.
 */
class CalcularResultadoAutoevaluacionUseCaseTest {

    private val repositorio = RepositorioAcademicoFalso()

    private val configuracion = ConfiguracionPonderaciones(
        caracteristicas = listOf(
            Caracteristica(id = "C1", nombre = "Característica 1", factor = "F1", ponderacion = 0.5),
            Caracteristica(id = "C2", nombre = "Característica 2", factor = "F1", ponderacion = 0.5),
            Caracteristica(id = "C3", nombre = "Característica 3", factor = "F2", ponderacion = 0.3),
            Caracteristica(id = "C4", nombre = "Característica 4", factor = "F2", ponderacion = 0.7),
        ),
        pesosFactores = mapOf("F1" to 0.6, "F2" to 0.4),
        pesoEncuestas = 0.4,
        pesoDocumental = 0.6,
    )

    private val useCase = CalcularResultadoAutoevaluacionUseCase(repositorio, configuracion)

    private fun registrarPregunta(
        codigoPregunta: String,
        caracteristica: String,
        promedio: Double?,
    ) {
        repositorio.guardarResultadoEncuestaPregunta(
            ResultadoEncuestaPregunta(
                programa = "EGSTI",
                periodo = "20261",
                codigoPregunta = codigoPregunta,
                caracteristica = caracteristica,
                estamentos = setOf(TipoEstamento.ESTUDIANTE),
                promedio = promedio,
            ),
        )
    }

    private fun registrarDocumental(caracteristica: String, calificacion: Double) {
        repositorio.guardarEvaluacionDocumental(
            EvaluacionDocumental(
                programa = "EGSTI",
                caracteristica = caracteristica,
                periodo = "20261",
                calificacion = calificacion,
            ),
        )
    }

    @Test
    fun `el resultado de encuesta de una caracteristica es el promedio de los promedios de sus preguntas`() {
        registrarPregunta("A1", "C1", 3.0)
        registrarPregunta("A2", "C1", 5.0)
        registrarDocumental("C1", 4.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        // encuesta = (3.0 + 5.0) / 2 = 4.0; promedio = 4.0*0.6 + 4.0*0.4 = 4.0
        assertEquals(4.0, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `las preguntas con promedio null no cuentan en el resultado de encuesta`() {
        registrarPregunta("A1", "C1", 4.0)
        registrarPregunta("A2", "C1", null)
        registrarDocumental("C1", 4.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        // encuesta = 4.0 (la pregunta ausente no cuenta); promedio = 4.0*0.6 + 4.0*0.4 = 4.0
        assertEquals(4.0, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `una caracteristica sin ninguna pregunta con valor tiene resultado de encuesta ausente`() {
        registrarPregunta("A1", "C1", null)
        registrarDocumental("C1", 4.7)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        // encuesta ausente -> el promedio es el valor documental completo, sin aplicar su peso de mezcla
        assertEquals(4.7, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `una caracteristica sin preguntas registradas tiene resultado de encuesta ausente`() {
        registrarDocumental("C1", 4.7)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertEquals(4.7, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `una caracteristica con encuesta y documental mezcla ambas fuentes con los pesos de la configuracion`() {
        registrarPregunta("A1", "C1", 2.0)
        registrarDocumental("C1", 5.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        // documental 5.0 * 0.6 + encuesta 2.0 * 0.4 = 3.0 + 0.8 = 3.8
        assertEquals(3.8, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `una caracteristica sin evaluacion documental es ausente aunque tenga encuesta`() {
        registrarPregunta("A1", "C1", 5.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promediosPorCaracteristica["C1"])
    }

    @Test
    fun `una caracteristica sin ninguna fuente es ausente`() {
        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promediosPorCaracteristica["C1"])
    }

    @Test
    fun `el promedio de un factor reponderan los pesos de las caracteristicas presentes`() {
        // C1 (peso 0.5) ausente; solo C2 (peso 0.5) tiene documental.
        registrarDocumental("C2", 4.4)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promediosPorCaracteristica["C1"])
        // reponderado: solo C2 presente -> su peso se normaliza a 1.0, el promedio del factor es su propio valor
        assertEquals(4.4, resultado.promediosPorFactor["F1"]!!, 1e-9)
    }

    @Test
    fun `el promedio de un factor con todas sus caracteristicas presentes no cambia por la reponderacion`() {
        registrarDocumental("C1", 4.0)
        registrarDocumental("C2", 5.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        // 4.0*0.5 + 5.0*0.5 = 4.5 (los pesos ya suman 1.0, reponderar no cambia nada)
        assertEquals(4.5, resultado.promediosPorFactor["F1"]!!, 1e-9)
    }

    @Test
    fun `un factor sin ninguna caracteristica calculable es ausente`() {
        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promediosPorFactor["F1"])
    }

    @Test
    fun `el promedio global reponderan los pesos de los factores presentes`() {
        // F1 (peso 0.6) ausente por completo; solo F2 (peso 0.4) tiene datos.
        registrarDocumental("C3", 4.0)
        registrarDocumental("C4", 4.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promediosPorFactor["F1"])
        // reponderado: solo F2 presente -> su peso se normaliza a 1.0
        assertEquals(4.0, resultado.promedioGlobal!!, 1e-9)
    }

    @Test
    fun `el promedio global con todos los factores y caracteristicas presentes no cambia por la reponderacion`() {
        registrarDocumental("C1", 4.0)
        registrarDocumental("C2", 5.0)
        registrarDocumental("C3", 3.0)
        registrarDocumental("C4", 4.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        val f1 = 4.0 * 0.5 + 5.0 * 0.5 // 4.5
        val f2 = 3.0 * 0.3 + 4.0 * 0.7 // 3.7
        val global = f1 * 0.6 + f2 * 0.4

        assertEquals(f1, resultado.promediosPorFactor["F1"]!!, 1e-9)
        assertEquals(f2, resultado.promediosPorFactor["F2"]!!, 1e-9)
        assertEquals(global, resultado.promedioGlobal!!, 1e-9)
    }

    @Test
    fun `el promedio global es ausente cuando ningun factor es calculable`() {
        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertNull(resultado.promedioGlobal)
    }

    @Test
    fun `el resultado conserva el catalogo completo de caracteristicas y factores aunque esten ausentes`() {
        registrarDocumental("C1", 4.0)

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertEquals(setOf("C1", "C2", "C3", "C4"), resultado.promediosPorCaracteristica.keys)
        assertEquals(setOf("F1", "F2"), resultado.promediosPorFactor.keys)
    }

    @Test
    fun `el resultado solo usa datos del programa y periodo consultados`() {
        registrarDocumental("C1", 4.0)
        repositorio.guardarEvaluacionDocumental(
            EvaluacionDocumental(programa = "OTRO-PROGRAMA", caracteristica = "C1", periodo = "20261", calificacion = 1.0),
        )
        repositorio.guardarEvaluacionDocumental(
            EvaluacionDocumental(programa = "EGSTI", caracteristica = "C1", periodo = "20252", calificacion = 1.0),
        )

        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertEquals(4.0, resultado.promediosPorCaracteristica["C1"]!!, 1e-9)
    }

    @Test
    fun `el resultado expone el programa y periodo consultados`() {
        val resultado = useCase.ejecutar("EGSTI", "20261")

        assertEquals("EGSTI", resultado.programa)
        assertEquals("20261", resultado.periodo)
    }
}

package com.example.sgva.domain

/**
 * Reglas de formato compartidas por las entidades del dominio. Centraliza la
 * verificación del formato `AAAAS` para que `Estudiante.cohorte` y
 * `Docente.periodo` apliquen exactamente el mismo criterio.
 */
internal object ReglasDeFormato {

    /** Regex de referencia definida en `DESIGN_SGVA.md`, Sección 0.1. */
    private val PATRON_PERIODO_ACADEMICO = Regex("""^\d{4}[12]$""")

    /**
     * Verifica que [valor] cumpla el formato `AAAAS` y lo devuelve sin cambios.
     *
     * @throws FormatoPeriodoInvalidoException si el formato no es válido.
     */
    fun exigirPeriodoAcademico(valor: String, campo: String): String {
        if (!PATRON_PERIODO_ACADEMICO.matches(valor)) {
            throw FormatoPeriodoInvalidoException(campo, valor)
        }
        return valor
    }

    /**
     * Verifica que [valor] no esté vacío ni en blanco y lo devuelve sin cambios.
     *
     * @throws CampoRequeridoVacioException si el valor está en blanco.
     */
    fun exigirNoVacio(valor: String, campo: String): String {
        if (valor.isBlank()) {
            throw CampoRequeridoVacioException(campo)
        }
        return valor
    }

    /**
     * Verifica que [valor] contenga al menos un elemento y lo devuelve sin
     * cambios. Aplica a los conjuntos obligatorios de la entidad (ej.
     * `ResultadoEncuestaPregunta.estamentos`).
     *
     * @throws CampoRequeridoVacioException si el conjunto está vacío.
     */
    fun <T> exigirNoVacio(valor: Set<T>, campo: String): Set<T> {
        if (valor.isEmpty()) {
            throw CampoRequeridoVacioException(campo)
        }
        return valor
    }

    /** Tolerancia numérica para las sumas de ponderaciones (`DESIGN_SGVA.md` §0.1). */
    const val TOLERANCIA_SUMA_PONDERACIONES: Double = 0.001

    /**
     * Verifica que [valor] no sea negativo y lo devuelve sin cambios. Aplica a
     * todo peso del modelo de ponderaciones (factores, características y
     * mezcla encuestas/documental; `DESIGN_SGVA.md` §0.1).
     *
     * @throws PonderacionNegativaException si [valor] es negativo.
     */
    fun exigirPonderacionNoNegativa(valor: Double, contexto: String): Double {
        if (valor < 0.0) {
            throw PonderacionNegativaException(contexto, valor)
        }
        return valor
    }

    /**
     * Verifica que [suma] sea igual a `1.0` dentro de
     * [TOLERANCIA_SUMA_PONDERACIONES] y la devuelve sin cambios.
     *
     * @throws SumaPonderacionesInvalidaException si [suma] se aleja de `1.0` más que la tolerancia.
     */
    fun exigirSumaUno(suma: Double, contexto: String): Double {
        if (kotlin.math.abs(suma - 1.0) > TOLERANCIA_SUMA_PONDERACIONES) {
            throw SumaPonderacionesInvalidaException(contexto, suma)
        }
        return suma
    }
}

